#!/usr/bin/python3
import binascii
import base64
import string
import re
from collections import Counter

def try_decode_methods(hex_string):
    results = []

    # Method 1: Try raw hex decode
    try:
        decoded = binascii.unhexlify(hex_string)
        results.append(("Raw hex", decoded))
    except:
        pass

    # Method 2: Try hex with ASCII
    try:
        decoded = bytes.fromhex(hex_string).decode('ascii', errors='ignore')
        results.append(("ASCII hex", decoded))
    except:
        pass

    # Method 3: Try Base64 after hex
    try:
        hex_decoded = binascii.unhexlify(hex_string)
        b64_decoded = base64.b64decode(hex_decoded)
        results.append(("Hex->Base64", b64_decoded))
    except:
        pass

    # Method 4: Try repeating hex decode
    try:
        current = hex_string
        for i in range(3):  # Try up to 3 levels deep
            current = binascii.unhexlify(current)
            results.append((f"Hex level {i+1}", current))
    except:
        pass

    return results

def analyze_decoded(decoded_data):
    print("\nAnalyzing decoded data:")

    # Check for printable strings
    if isinstance(decoded_data, bytes):
        printable = ''.join(chr(x) for x in decoded_data if chr(x) in string.printable)
    else:
        printable = ''.join(c for c in decoded_data if c in string.printable)

    print(f"Printable characters: {printable[:200]}...")

    # Look for flag format
    flag_pattern = re.compile(rb'csawctf{[^}]*}' if isinstance(decoded_data, bytes) else r'csawctf{[^}]*}')
    if isinstance(decoded_data, bytes):
        matches = flag_pattern.findall(decoded_data)
    else:
        matches = flag_pattern.findall(decoded_data)
    if matches:
        print("Found potential flags:", matches)

    # Check character frequency
    if isinstance(decoded_data, bytes):
        freq = Counter(decoded_data)
    else:
        freq = Counter(decoded_data)
    print("\nMost common bytes/chars:")
    for char, count in freq.most_common(10):
        if isinstance(char, int):
            print(f"0x{char:02x}: {count}")
        else:
            print(f"{char}: {count}")

def main():
    # Read the hex string from file
    with open('/home/ctfplayer/ctf_files/vars/main.yml', 'r') as f:
        content = f.read()
        # Extract sus14 value
        for line in content.split('\n'):
            if line.startswith('sus14:'):
                hex_string = line.split(': ')[1].strip('"')
                break

    print(f"Original hex string length: {len(hex_string)}")
    results = try_decode_methods(hex_string)

    for method, decoded in results:
        print(f"\n=== {method} Decoding ===")
        analyze_decoded(decoded)

if __name__ == "__main__":
    main()
